mapper.select:
select prodId, /* 产品代码 */ finprodName, /* 产品名称 */ serialNo, /* 业务流水号 */ interType, /* 对账对象 */ xmlStatus, /* 报文状态 */ checkStatus, /* 对账状态 */ valDate, /* 估值日期 */ remark, /* 备注 */ returnTxt /* 接收信息 */ from (SELECT BASI.ACCT_SUBJECT_ID prodId, BASI.ACCT_SUBJECT_NAME finprodName, SIV.SERIALNO serialNo, #{INTER_TYPE_VAL,jdbcType=VARCHAR} interType, DECODE(SIV.XML_STATUS, null, 0, SIV.XML_STATUS) xmlStatus, DECODE(SIV.CHECK_STATUS, null, 0, SIV.CHECK_STATUS) checkStatus, TO_CHAR(BVTD.VAL_DATE, 'yyyyMMdd') valDate, SIV.REMARK remark, SIV.RETURN_TXT returnTxt FROM (SELECT DISTINCT A.BOOKSET_ID, A.VAL_DATE FROM BOK_VAL_TABLE_DATA A)BVTD LEFT JOIN BOK_BOOKSET BB ON BVTD.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON BB.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = BB.ACCT_SUBJECT_TYPE LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = BB.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = #{INTER_TYPE_VAL,jdbcType=VARCHAR} AND SIV.CDATE = TO_CHAR(BVTD.VAL_DATE, 'yyyyMMdd')) where 1 = 1
AND prodId IN
#{item}
and valDate = to_char(to_date(#{valDate,jdbcType=DATE},'yyyy-MM-dd'),'yyyyMMdd') and xmlStatus = #{xmlStatus,jdbcType=VARCHAR} and checkStatus = #{checkStatus,jdbcType=VARCHAR} and #{INTER_TYPE_VAL,jdbcType=VARCHAR} = #{interType,jdbcType=VARCHAR} union select prodId, /* 产品代码 */ finprodName, /* 产品名称 */ serialNo, /* 业务流水号 */ interType, /* 对账对象 */ xmlStatus, /* 报文状态 */ checkStatus, /* 对账状态 */ valDate, /* 估值日期 */ remark, /* 备注 */ returnTxt /* 接收信息 */ from (SELECT BASI.ACCT_SUBJECT_ID prodId, BASI.ACCT_SUBJECT_NAME finprodName, SIV.SERIALNO serialNo, #{INTER_TYPE_BALANCEL,jdbcType=VARCHAR} interType, DECODE(SIV.XML_STATUS, null, 0, SIV.XML_STATUS) xmlStatus, DECODE(SIV.CHECK_STATUS, null, 0, SIV.CHECK_STATUS) checkStatus, TO_CHAR(B.BALANCE_DATE, 'yyyyMMdd') valDate, SIV.REMARK remark, SIV.RETURN_TXT returnTxt FROM (SELECT DISTINCT A.BOOKSET_ID, A.BALANCE_DATE FROM BOK_BALANCE A)B LEFT JOIN BOK_BOOKSET BB ON B.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON BB.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = BB.ACCT_SUBJECT_TYPE LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = BB.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = #{INTER_TYPE_BALANCEL,jdbcType=VARCHAR} AND SIV.CDATE = TO_CHAR(B.BALANCE_DATE, 'yyyyMMdd')) where 1 = 1
AND prodId IN
#{item}
and valDate = to_char(to_date(#{valDate,jdbcType=DATE},'yyyy-MM-dd'),'yyyyMMdd') and xmlStatus = #{xmlStatus,jdbcType=VARCHAR} and checkStatus = #{checkStatus,jdbcType=VARCHAR} and #{INTER_TYPE_BALANCEL,jdbcType=VARCHAR} = #{interType,jdbcType=VARCHAR}
